    lesson_ENT_18_title: "المتاجر الإلكترونية",
    lesson_ENT_18_body: "**التجارة الإلكترونية** هي بيع الأشياء عبر الإنترنت. يمكنك البيع للناس وأنت بملابس النوم! (مهلاً، أعني، يمكنك البقاء في بيجامتك أثناء البيع للناس حول العالم). أمازون و eBay متاجر إلكترونية ضخمة.",
