    lesson_ENT_19_title: "التعليقات والتحسين",
    lesson_ENT_19_body: "**التعليقات (Feedback)** هي عندما يخبرك شخص ما برأيه. إذا قال 10 أشخاص أن كعكاتك طعمها مثل الملح، توقف عن وضع الملح فيها! الاستماع للتعليقات يساعدك على جعل منتجك أفضل وعملائك أسعد.",
