    // MODULE 3: Investing
    lesson_INV_21_title: "ما هو الاستثمار؟",
    lesson_INV_21_body: "**الاستثمار** هو جعل مالك يعمل من أجلك. إنه مثل زرع شجرة مال. 🌳 تشتري شيئاً اليوم (مثل كتاب قصص مصورة نادر أو سهم)، على أمل أن يصبح ذا قيمة أكبر غداً. إنه أمر محفوف بالمخاطر، لكنه مثير!",
    lesson_INV_21_question: "ما هو هدف الاستثمار؟",
    lesson_INV_21_flavor: "بداية رائعة! لقد زرعت بذرة شجرة المال الأولى.",
    lesson_INV_21_answer_correct: "لجعل المال ينمو",
    lesson_INV_21_distractor_0: "لإنفاق المال بسرعة",
    lesson_INV_21_distractor_1: "لإخفاء المال في حذاء",
    lesson_INV_21_distractor_2: "لخسارة المال عمداً",

    lesson_INV_22_title: "الأسهم للأطفال",
    lesson_INV_22_body: "**السهم** هو شريحة صغيرة جداً من شركة. إذا اشتريت سهماً واحداً في ديزني، فأنت تقنياً تملك قطعة صغيرة من ميكي ماوس! 🐭 إذا أبلت الشركة بلاءً حسناً، تصبح شريحتك أكثر قيمة.",
    lesson_INV_22_question: "ماذا تملك إذا اشتريت سهماً؟",
    lesson_INV_22_flavor: "تنبيه المالك! لقد اشتريت للتو حصتك الأولى في شركة.",
    lesson_INV_22_answer_correct: "قطعة صغيرة من شركة",
    lesson_INV_22_distractor_0: "مخزون من الألعاب المجانية",
    lesson_INV_22_distractor_1: "سيارة المدير",
    lesson_INV_22_distractor_2: "مجرد ورقة",

    lesson_INV_23_title: "الفائدة المركبة",
    lesson_INV_23_body: "**الفائدة المركبة** هي أعجوبة العالم الثامنة! 🌎 إنها مثل كرة ثلج تتدحرج أسفل التل. فائدتك تكسب المزيد من الفائدة. ابدأ الادخار صغيراً، وسينمو مالك بشكل ضخم عندما تكبر!",
    lesson_INV_23_question: "ما التأثير الذي تحدثه الفائدة المركبة؟",
    lesson_INV_23_flavor: "إنها ضخمة! كرة ثلج مالك تتدحرج بسرعة الآن.",
    lesson_INV_23_answer_correct: "تأثير كرة الثلج (ينمو بشكل أسرع)",
    lesson_INV_23_distractor_0: "تأثير ذوبان الجليد",
    lesson_INV_23_distractor_1: "خدعة الاختفاء",
    lesson_INV_23_distractor_2: "تأثير الإطار المثقوب",

    lesson_INV_24_title: "أساسيات العقارات",
    lesson_INV_24_body: "**العقارات** تعني الأراضي والمباني. إنها لعبة 'مونوبولي' في الحياة الحقيقية! 🏠 يمكنك شراء منزل والسماح لشخص آخر بالعيش فيه. يدفعون لك **إيجاراً** كل شهر. إنه مثل مصفوفة من غريب!",
    lesson_INV_24_question: "ماذا يسمى المال المدفوع للعيش في منزل شخص آخر؟",
    lesson_INV_24_flavor: "تـم تسليم المفاتيح! لقد جمعت الإيجار من عقارك.",
