    lesson_INV_25_distractor_2: "شراء الحلوى",

    lesson_INV_26_title: "التنويع",
    lesson_INV_26_body: "لا تضع كل بيضك في سلة واحدة! 🥚 **التنويع** يعني شراء أشياء مختلفة. اشترِ بعض الأسهم، وبعض السندات، وربما بطاقة بوكيمون نادرة. إذا أسقطت سلة البيض، فعلى الأقل لا يزال لديك البطاقات!",
