    lesson_INV_27_title: "المخاطرة مقابل المكافأة",
    lesson_INV_27_body: "الاستثمار مثل الأفعوانية. 🎢 **المخاطرة** العالية تعني أنك قد تخسر المال، لكنك قد تجني الكثير أيضاً (مكافأة عالية). المخاطرة المنخفضة أكثر أماناً لكنها مملة. عليك أن تقرر مدى شجاعتك!",
    lesson_INV_27_question: "إذا كان الاستثمار عالي المخاطرة، فما هو الصحيح عادة؟",
    lesson_INV_27_flavor: "لقد جازفت! المخاطرة أثمرت هذه المرة.",
