    lesson_INV_28_title: "مستثمرون مشهورون",
    lesson_INV_28_body: "وارن بافيت جد ثري جداً لأنه بدأ الاستثمار عندما كان في الحادية عشرة من عمره! يشرب كولا الكرز ويقرأ الكتب طوال اليوم. سره؟ يشتري شركات جيدة ويحتفظ بها إلى الأبد.",
