    lesson_INV_28_distractor_2: "اخترع الإنترنت",

    lesson_INV_29_title: "الاستثمار في نفسك",
    lesson_INV_29_body: "أفضل استثمار هو أنت! 🧠 تعلم البرمجة، الرسم، أو التحدث بالإسبانية يزيد من **رأس مالك البشري**. كلما كنت أذكى، زادت المشاكل التي يمكنك حلها (وتقاضي أجراً مقابلها!).",
    lesson_INV_29_question: "كيف تستثمر في نفسك؟",
