    // MODULE 4: Marketing
    lesson_MKT_31_title: "ما هو التسويق؟",
    lesson_MKT_31_body: "**التسويق** هو فن إخبار الناس عن أشيائك. إذا خبزت أفضل كعكة في العالم لكن أخفيتها تحت سريرك، فلن يشتريها أحد! التسويق يساعدك على الصراخ 'لدي كعك!' بطريقة رائعة.",
