    lesson_MKT_34_title: "الإعلانات التجارية والأناشيد",
    lesson_MKT_34_body: "'با دا با با با، أنا أحبه!' 🎵 **النغمة الإعلانية (Jingle)** هي أغنية جذابة تعلق في دماغك إلى الأبد. إنها خدعة تسويقية لتجعلك تتذكر اسم العلامة التجارية طوال اليوم.",
