    lesson_MKT_37_title: "التغليف مهم",
    lesson_MKT_37_body: "هل سبق لك شراء حبوب إفطار فقط لأن العلبة بدت رائعة؟ 🥣 هذا هو **التغليف**. العلبة مثل زي لمنتجك. إذا بدت مملة، قد يعتقد الناس أن الطعام بداخلها ممل أيضاً!",
