    lesson_GLO_88_title: "المناطق الزمنية",
    lesson_GLO_88_body: "عندما تأكل غداءك في نيويورك، يكون الناس في طوكيو نائمين! 😴 **المناطق الزمنية** تعني أن الوقت مختلف حول العالم. إذا اتصلت بشريكك التجاري في وقت خاطئ، ستوقظه. ليس جيداً!",
