    // MODULE 10: Finanical Smarts
    lesson_FIN_91_title: "بطاقات الائتمان",
    lesson_FIN_91_body: "بطاقات الائتمان ليست مالاً سحرياً! 💳 عندما تمررها، يقرضك البنك المال. عليك سداده لاحقاً. إذا لم تفعل، يغضب البنك ويتقاضى منك المزيد (فائدة). استخدمها بحكمة!",
    lesson_FIN_91_question: "من أين يأتي المال عند استخدام بطاقة الائتمان؟",
    lesson_FIN_91_flavor: "تمريرة ذكية! دفعت فاتورة بطاقتك بالكامل لتجنب الرسوم.",
