    lesson_FIN_92_distractor_2: "الائتمان يستخدم مالك",

    lesson_FIN_93_title: "الديون: جيد مقابل سيء",
    lesson_FIN_93_body: "**الدين** هو المال الذي تدين به. الدين السيء هو اقتراض المال للحلوى (التي تختفي). الدين الجيد هو اقتراض المال للذهاب إلى الكلية أو بدء عمل تجاري (مما يجعلك تكسب المزيد من المال لاحقاً).",
    lesson_FIN_93_question: "ما هو مثال على الدين الجيد؟",
    lesson_FIN_93_flavor: "اقتراض ذكي! حصلت على قرض لفتح متجرك.",
    lesson_FIN_93_answer_correct: "قرض للاستثمار (مثل التعليم أو العمل)",
