    lesson_FIN_96_title: "صافي الثروة",
    lesson_FIN_96_body: "صافي ثروتك هو: (كل ما تملكه) ناقص (كل ما تدين به). 💰\n\nتملك: 10 دولارات و دراجة.\nتدين لصديقك: 2 دولار.\nصافي الثروة: 8 دولارات + دراجة.\nإنه بطاقة قياس ثروتك.",
