    lesson_FIN_99_title: "قراءة الراتب",
    lesson_FIN_99_body: "عندما تحصل على وظيفة، لا تحصل على كل المال. الشيك يظهر 'الدخل الإجمالي' (ما كسبته) و 'الدخل الصافي' (ما تأخذه للمنزل بعد الضرائب). إنه لأمر محزن أن ترى المال يختفي، لكنه يدفع للمدارس!",
